 68→export function getActiveLoginMethod(): string | undefined {
 69→  const accountDb = getAccountDb();
 70→  const row = accountDb.first('SELECT method FROM auth WHERE active = 1');
 71→  return (row as { method?: string } | null)?.method;
 72→}
 73→
 74→/*
 75→ * Get the Login Method in the following order
 76→ * req (the frontend can say which method in the case it wants to resort to forcing password auth)
 77→ * config options
 78→ * fall back to using password
 79→ */
 80→export function getLoginMethod(req?: {
 81→  body?: { loginMethod?: string };
 82→}): string {
 83→  if (
 84→    typeof req !== 'undefined' &&
 85→    (req.body || { loginMethod: null }).loginMethod &&
 86→    config.get('allowedLoginMethods').includes(req.body!.loginMethod!)
 87→  ) {
 88→    return req.body!.loginMethod!;
 89→  }
 90→
 91→  //BY-PASS ANY OTHER CONFIGURATION TO ENSURE HEADER AUTH
 92→  if (
 93→    config.get('loginMethod') === 'header' &&
 94→    config.get('allowedLoginMethods').includes('header')
 95→  ) {
 96→    return config.get('loginMethod');
 97→  }
 98→
 99→  const activeMethod = getActiveLoginMethod();
100→  return activeMethod || config.get('loginMethod');
101→}
102→
103→interface LoginSettings {
104→  password?: string;
105→  openId?: Record<string, unknown>;
106→}
107→
108→interface BootstrapResult {
109→  error?: string;
110→  token?: string;
111→}
112→
113→export async function bootstrap(
114→  loginSettings: LoginSettings | null,
115→  forced: boolean = false,
116→): Promise<BootstrapResult> {
117→  if (!loginSettings) {
118→    return { error: 'invalid-login-settings' };
119→  }
120→  const passEnabled = 'password' in loginSettings;
121→  const openIdEnabled = 'openId' in loginSettings;
122→
123→  const accountDb = getAccountDb();
124→  accountDb.mutate('BEGIN TRANSACTION');
125→  try {
126→    const countRow = accountDb.first(
127→      `SELECT count(*) as countOfOwner
128→   FROM users
129→   WHERE users.user_name <> '' and users.owner = 1`,
130→    );
131→    const countOfOwner =
132→      (countRow as { countOfOwner?: number } | null)?.countOfOwner ?? 0;
133→
134→    if (!forced && (!openIdEnabled || countOfOwner > 0)) {
135→      if (!needsBootstrap()) {
136→        accountDb.mutate('ROLLBACK');
137→        return { error: 'already-bootstrapped' };
138→      }
139→    }
140→
141→    if (!passEnabled && !openIdEnabled) {
142→      accountDb.mutate('ROLLBACK');
143→      return { error: 'no-auth-method-selected' };
144→    }
145→
146→    if (passEnabled && openIdEnabled && !forced) {
147→      accountDb.mutate('ROLLBACK');
148→      return { error: 'max-one-method-allowed' };
149→    }
150→
151→    if (passEnabled) {
152→      const { error } = bootstrapPassword(loginSettings.password!);
153→      if (error) {
154→        accountDb.mutate('ROLLBACK');
155→        return { error };
156→      }
157→    }
158→
159→    if (openIdEnabled && forced) {
160→      const { error } = await bootstrapOpenId(loginSettings.openId!);
161→      if (error) {
162→        accountDb.mutate('ROLLBACK');
163→        return { error };
164→      }
165→    }
166→
167→    accountDb.mutate('COMMIT');
168→    return passEnabled ? loginWithPassword(loginSettings.password!) : {};
169→  } catch (error) {
170→    accountDb.mutate('ROLLBACK');
171→    throw error;
172→  }
173→}
174→
175→export function isAdmin(userId: string): boolean {
176→  return hasPermission(userId, 'ADMIN');
177→}
178→
179→export function hasPermission(userId: string, permission: string): boolean {
180→  return getUserPermission(userId) === permission;
181→}
182→
183→export async function enableOpenID(
184→  loginSettings: LoginSettings | null,
185→): Promise<{ error?: string } | undefined> {
186→  if (!loginSettings || !loginSettings.openId) {
187→    return { error: 'invalid-login-settings' };
188→  }
189→
190→  const { error } = (await bootstrapOpenId(loginSettings.openId)) || {};
191→  if (error) {
192→    return { error };
193→  }
194→
195→  getAccountDb().mutate('DELETE FROM sessions');
196→}
197→
198→export async function disableOpenID(
199→  loginSettings: { password?: string } | null,
200→): Promise<{ error?: string } | undefined> {
201→  if (!loginSettings || !loginSettings.password) {
202→    return { error: 'invalid-login-settings' };
203→  }
204→
205→  const accountDb = getAccountDb();
206→  const authRow = accountDb.first(
207→    'SELECT extra_data FROM auth WHERE method = ?',
208→    ['password'],
209→  );
210→  const passwordHash = (authRow as { extra_data?: string } | null)?.extra_data;
211→
212→  if (!passwordHash) {
213→    return { error: 'invalid-password' };
214→  }
215→
216→  if (!loginSettings?.password) {
217→    return { error: 'invalid-password' };
218→  }
219→
220→  if (passwordHash) {
221→    const confirmed = bcrypt.compareSync(loginSettings.password, passwordHash);
222→
223→    if (!confirmed) {
224→      return { error: 'invalid-password' };
225→    }
226→  }
227→
228→  const { error } = (await bootstrapPassword(loginSettings.password)) || {};
229→  if (error) {
230→    return { error };
231→  }
232→
233→  try {
234→    accountDb.transaction(() => {
235→      accountDb.mutate('DELETE FROM sessions');
236→      accountDb.mutate(
237→        `DELETE FROM user_access
238→                              WHERE user_access.user_id IN (
239→                                  SELECT users.id
240→                                  FROM users
241→                                  WHERE users.user_name <> ?
242→                              );`,
243→        [''],
244→      );
245→      accountDb.mutate('DELETE FROM users WHERE user_name <> ?', ['']);
246→      accountDb.mutate('DELETE FROM auth WHERE method = ?', ['openid']);
247→    });
248→  } catch (err) {
249→    console.error('Error cleaning up openid information:', err);
250→    return { error: 'database-error' };
251→  }
252→}
