305→  const accountDb = getAccountDb();
306→
307→  if (!prefs) {
308→    return;
309→  }
310→
311→  accountDb.transaction(() => {
312→    Object.entries(prefs).forEach(([key, value]) => {
313→      accountDb.mutate(
314→        'INSERT INTO server_prefs (key, value) VALUES (?, ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value',
315→        [key, value],
316→      );
317→    });
318→  });
319→}
