321→export function clearExpiredSessions(): void {
322→  const clearThreshold = Math.floor(Date.now() / 1000) - 3600;
323→
324→  const deletedSessions = getAccountDb().mutate(
325→    'DELETE FROM sessions WHERE expires_at <> -1 and expires_at < ?',
326→    [clearThreshold],
