 6→export type AuditEventType =
 7→  | 'login_success'
 8→  | 'login_failure'
 9→  | 'bootstrap'
10→  | 'password_change'
11→  | 'openid_auth'
12→  | 'eb_consent_auth'
13→  | 'eb_consent_expiry'
14→  | 'eb_consent_renewal'
15→  | 'eb_account_link';
16→
17→function hashActor(token: string): string {
18→  return createHash('sha256').update(token).digest('hex').slice(0, 8);
19→}
20→
21→export function writeAuditLog(opts: {
22→  event_type: AuditEventType;
23→  actor: string;
24→  ip_address?: string;
25→  outcome: 'success' | 'fail';
26→  details?: Record<string, unknown>;
27→}): void {
28→  try {
29→    const db = getAccountDb();
30→    const actorValue =
31→      opts.actor === 'system' ? 'system' : hashActor(opts.actor);
32→    db.mutate(
33→      `INSERT INTO audit_log (event_type, actor, ip_address, outcome, details)
34→       VALUES (?, ?, ?, ?, ?)`,
35→      [
36→        opts.event_type,
37→        actorValue,
38→        opts.ip_address ?? null,
39→        opts.outcome,
40→        opts.details ? JSON.stringify(opts.details) : null,
41→      ],
42→    );
43→  } catch (err) {
44→    logger.error('audit log write failed', {
45→      error: String(err),
46→      event_type: opts.event_type,
47→    });
48→  }
49→}
