 25→
 26→  let paths = [];
 27→  if (await fs.exists(backupDir)) {
 28→    paths = await fs.listDir(backupDir);
 29→    paths = paths.filter(file => file.match(/\.sqlite$/));
 30→  }
 31→
 32→  const backups = await Promise.all(
 33→    paths.map(async path => {
 34→      const mtime = await fs.getModifiedTime(fs.join(backupDir, path));
 35→      return {
 36→        id: path,
 37→        date: new Date(mtime),
 38→      };
 39→    }),
 40→  );
 41→
 42→  backups.sort((b1, b2) => {
 43→    if (b1.date < b2.date) {
 44→      return 1;
 45→    } else if (b1.date > b2.date) {
 46→      return -1;
 47→    }
 48→    return 0;
 49→  });
 50→
 51→  return backups;
 52→}
 53→
 54→async function getLatestBackup(id: string): Promise<LatestBackup | null> {
 55→  const budgetDir = fs.getBudgetDir(id);
 56→  if (await fs.exists(fs.join(budgetDir, LATEST_BACKUP_FILENAME))) {
 57→    return {
 58→      id: LATEST_BACKUP_FILENAME,
 59→      date: null,
 60→      isLatest: true,
 61→    };
 62→  }
 63→  return null;
 64→}
 65→
 66→export async function getAvailableBackups(id: string): Promise<Backup[]> {
 67→  const backups = await getBackups(id);
 68→
 69→  const latestBackup = await getLatestBackup(id);
 70→  if (latestBackup) {
 71→    backups.unshift(latestBackup);
 72→  }
 73→
 74→  return backups.map(backup => ({
 75→    ...backup,
 76→    date: backup.date ? dateFns.format(backup.date, 'yyyy-MM-dd H:mm') : null,
 77→  }));
 78→}
 79→
 80→export async function updateBackups(backups) {
 81→  const byDay = backups.reduce((groups, backup) => {
 82→    const day = dateFns.format(backup.date, 'yyyy-MM-dd');
 83→    groups[day] = groups[day] || [];
 84→    groups[day].push(backup);
 85→    return groups;
 86→  }, {});
 87→
 88→  const removed = [];
 89→  for (const day of Object.keys(byDay)) {
 90→    const dayBackups = byDay[day];
 91→    const isToday = day === monthUtils.currentDay();
 92→    // Allow 3 backups of the current day (so fine-grained edits are
 93→    // kept around). Otherwise only keep around one backup per day.
 94→    // And only keep a total of 10 backups.
 95→    for (const backup of dayBackups.slice(isToday ? 3 : 1)) {
 96→      removed.push(backup.id);
 97→    }
 98→  }
 99→
100→  // Get the list of remaining backups and only keep the latest 10
101→  const currentBackups = backups.filter(backup => !removed.includes(backup.id));
102→  return removed.concat(currentBackups.slice(10).map(backup => backup.id));
103→}
104→
105→export async function makeBackup(id: string) {
106→  const budgetDir = fs.getBudgetDir(id);
107→
108→  // When making a backup, we no longer consider the user to be
109→  // viewing any backups. If there exists a "latest backup" we should
110→  // delete it and consider whatever is current as the latest
111→  if (await fs.exists(fs.join(budgetDir, LATEST_BACKUP_FILENAME))) {
112→    await fs.removeFile(fs.join(fs.getBudgetDir(id), LATEST_BACKUP_FILENAME));
113→  }
114→
115→  const backupId = `${uuidv4()}.sqlite`;
116→  const backupPath = fs.join(budgetDir, 'backups', backupId);
117→
118→  if (!(await fs.exists(fs.join(budgetDir, 'backups')))) {
119→    await fs.mkdir(fs.join(budgetDir, 'backups'));
120→  }
121→
122→  await fs.copyFile(fs.join(budgetDir, 'db.sqlite'), backupPath);
123→
124→  // Remove all the messages from the backup
125→  const db = sqlite.openDatabase(backupPath);
126→  await sqlite.runQuery(db, 'DELETE FROM messages_crdt');
127→  await sqlite.runQuery(db, 'DELETE FROM messages_clock');
128→  sqlite.closeDatabase(db);
129→
130→  const toRemove = await updateBackups(await getBackups(id));
131→  for (const id of toRemove) {
132→    await fs.removeFile(fs.join(budgetDir, 'backups', id));
133→  }
134→
135→  connection.send('backups-updated', await getAvailableBackups(id));
136→}
137→
138→export async function loadBackup(id: string, backupId: string) {
139→  const budgetDir = fs.getBudgetDir(id);
140→
141→  if (!(await fs.exists(fs.join(budgetDir, LATEST_BACKUP_FILENAME)))) {
142→    // If this is the first time we're loading a backup, save the
143→    // current version so the user can easily revert back to it
144→    await fs.copyFile(
145→      fs.join(budgetDir, 'db.sqlite'),
146→      fs.join(budgetDir, LATEST_BACKUP_FILENAME),
147→    );
148→
149→    await fs.copyFile(
150→      fs.join(budgetDir, 'metadata.json'),
151→      fs.join(budgetDir, 'metadata.latest.json'),
152→    );
153→
154→    // Restart the backup service to make sure the user has the full
155→    // amount of time to figure out which one they want
156→    stopBackupService();
157→    startBackupService(id);
158→
159→    await prefs.loadPrefs(id);
160→  }
161→
162→  if (backupId === LATEST_BACKUP_FILENAME) {
163→    logger.log('Reverting backup');
164→
165→    // If reverting back to the latest, copy and delete the latest
166→    // backup
167→    await fs.copyFile(
168→      fs.join(budgetDir, LATEST_BACKUP_FILENAME),
169→      fs.join(budgetDir, 'db.sqlite'),
170→    );
171→    await fs.copyFile(
172→      fs.join(budgetDir, 'metadata.latest.json'),
173→      fs.join(budgetDir, 'metadata.json'),
174→    );
175→    await fs.removeFile(fs.join(budgetDir, LATEST_BACKUP_FILENAME));
176→    await fs.removeFile(fs.join(budgetDir, 'metadata.latest.json'));
177→
178→    // Re-upload the new file
179→    try {
180→      await cloudStorage.upload();
181→    } catch {}
182→    prefs.unloadPrefs();
183→  } else {
184→    logger.log('Loading backup', backupId);
185→
186→    // This function is only ever called when a budget isn't loaded,
187→    // so it's safe to load our prefs in. We need to forget about any
188→    // syncing data if we are loading a backup (the current sync data
189→    // will be restored if the user reverts to the original version)
190→    await prefs.loadPrefs(id);
191→    await prefs.savePrefs({
192→      groupId: null,
193→      lastSyncedTimestamp: null,
194→      lastUploaded: null,
195→    });
196→
197→    // Re-upload the new file
198→    try {
199→      await cloudStorage.upload();
200→    } catch {}
201→
202→    prefs.unloadPrefs();
203→
204→    await fs.copyFile(
205→      fs.join(budgetDir, 'backups', backupId),
206→      fs.join(budgetDir, 'db.sqlite'),
207→    );
208→  }
209→}
210→
211→export function startBackupService(id: string) {
212→  if (serviceInterval) {
213→    clearInterval(serviceInterval);
214→  }
215→
216→  // Make a backup every 15 minutes
217→  serviceInterval = setInterval(
218→    async () => {
219→      logger.log('Making backup');
220→      await makeBackup(id);
221→    },
222→    1000 * 60 * 15,
223→  );
224→}
225→
226→export function stopBackupService() {
227→  clearInterval(serviceInterval);
228→  serviceInterval = null;
229→}
