  1→// @ts-strict-ignore
  2→import SQL from 'better-sqlite3';
  3→import { v4 as uuidv4 } from 'uuid';
  4→
  5→import { readFile, removeFile } from '../fs';
  6→import { logger } from '../log';
  7→
  8→import { normalise } from './normalise';
  9→import { unicodeLike } from './unicodeLike';
 10→
 11→function verifyParamTypes(sql, arr) {
 12→  arr.forEach(val => {
 13→    if (typeof val !== 'string' && typeof val !== 'number' && val !== null) {
 14→      logger.log(sql, arr);
 15→      throw new Error('Invalid field type ' + val + ' for sql ' + sql);
 16→    }
 17→  });
 18→}
 19→
 20→export async function init() {
 21→  // No need to initialise on electron
 22→}
 23→
 24→export function prepare(db, sql) {
 25→  return db.prepare(sql);
 26→}
 27→
 28→export function runQuery(
 29→  db: SQL.Database,
 30→  sql: string | SQL.Statement,
 31→  params: (string | number)[] = [],
 32→  fetchAll = false,
 33→) {
 34→  if (params) {
 35→    verifyParamTypes(sql, params);
 36→  }
 37→
 38→  let stmt: SQL.Statement;
 39→  try {
 40→    stmt = typeof sql === 'string' ? db.prepare(sql) : sql;
 41→  } catch (e) {
 42→    logger.log('error', sql);
 43→    throw e;
 44→  }
 45→
 46→  if (fetchAll) {
 47→    try {
 48→      const result = stmt.all(...params);
 49→      return result;
 50→    } catch (e) {
 51→      logger.log('error', sql);
 52→      throw e;
 53→    }
 54→  } else {
 55→    const info = stmt.run(...params);
 56→    return { changes: info.changes, insertId: info.lastInsertRowid };
 57→  }
 58→}
 59→
 60→export function execQuery(db: SQL.Database, sql: string) {
 61→  db.exec(sql);
 62→}
 63→
 64→export function transaction(db: SQL.Database, fn: () => void) {
 65→  db.transaction(fn)();
 66→}
 67→
 68→// **Important**: this is an unsafe function since sqlite executes
 69→// executes statements sequentially. It would be easy for other code
 70→// to run statements in between our transaction and get caught up in
 71→// it. This is rarely used, and only needed for specific cases (like
 72→// batch importing a bunch of data). Don't use this.
 73→let transactionDepth = 0;
 74→export async function asyncTransaction(
 75→  db: SQL.Database,
 76→  fn: () => Promise<void>,
 77→) {
 78→  // Support nested transactions by "coalescing" them into the parent
 79→  // one if one is already started
 80→  if (transactionDepth === 0) {
 81→    db.exec('BEGIN TRANSACTION');
 82→  }
 83→  transactionDepth++;
 84→
 85→  try {
 86→    await fn();
 87→  } finally {
 88→    transactionDepth--;
 89→    // We always commit because rollback is more dangerous - any
 90→    // queries that ran *in-between* this async function would be
 91→    // lost. Right now we are only using transactions for speed
 92→    // purposes unfortunately
 93→    if (transactionDepth === 0) {
 94→      db.exec('COMMIT');
 95→    }
 96→  }
 97→}
 98→
 99→function regexp(regex: string, text: string | null) {
100→  return new RegExp(regex).test(text || '') ? 1 : 0;
101→}
102→
103→export function openDatabase(pathOrBuffer: string | Buffer) {
104→  const db = new SQL(pathOrBuffer);
105→  // Define Unicode-aware LOWER, UPPER, and LIKE implementation.
106→  // This is necessary because better-sqlite3 uses SQLite build without ICU support.
107→  db.function('UNICODE_LOWER', { deterministic: true }, (arg: string | null) =>
108→    arg?.toLowerCase(),
109→  );
110→  db.function('UNICODE_UPPER', { deterministic: true }, (arg: string | null) =>
111→    arg?.toUpperCase(),
112→  );
113→  db.function('UNICODE_LIKE', { deterministic: true }, unicodeLike);
114→  db.function('REGEXP', { deterministic: true }, regexp);
115→  db.function('NORMALISE', { deterministic: true }, normalise);
116→  return db;
117→}
118→
119→export function closeDatabase(db: SQL.Database) {
120→  return db.close();
121→}
122→
123→export async function exportDatabase(db: SQL.Database) {
124→  // electron does not support better-sqlite serialize since v21
125→  // save to file and read in the raw data.
126→  const name = `${process.env.ACTUAL_DATA_DIR}/backup-for-export-${uuidv4()}.db`;
127→
128→  await db.backup(name);
129→
130→  const data = await readFile(name, 'binary');
131→  await removeFile(name);
132→
133→  return data;
134→}
