 1→import Database from 'better-sqlite3';
 2→
 3→export interface MutateResult {
 4→  changes: number;
 5→  insertId: number | bigint;
 6→}
 7→
 8→export class WrappedDatabase {
 9→  private db: Database.Database;
10→
11→  constructor(db: Database.Database) {
12→    this.db = db;
13→  }
14→
15→  all(sql: string, params: unknown[] = []): Record<string, unknown>[] {
16→    const stmt = this.db.prepare(sql);
17→    return stmt.all(...params) as Record<string, unknown>[];
18→  }
19→
20→  first(sql: string, params: unknown[] = []): Record<string, unknown> | null {
21→    const rows = this.all(sql, params);
22→    return rows.length === 0 ? null : rows[0];
23→  }
24→
25→  exec(sql: string): Database.Database {
26→    return this.db.exec(sql);
27→  }
28→
29→  mutate(sql: string, params: unknown[] = []): MutateResult {
30→    const stmt = this.db.prepare(sql);
31→    const info = stmt.run(...params);
32→    return { changes: info.changes, insertId: info.lastInsertRowid };
33→  }
34→
35→  transaction(fn: () => void): void {
36→    this.db.transaction(fn)();
37→  }
38→
39→  close(): void {
40→    this.db.close();
41→  }
42→}
43→
44→export function openDatabase(filename: string): WrappedDatabase {
45→  return new WrappedDatabase(new Database(filename));
46→}
