 1→import logger from './logger.js';
 2→
 3→type Severity = 'info' | 'warning' | 'error';
 4→
 5→export type StoredAlert = {
 6→  id: string;
 7→  event_type: string;
 8→  message: string;
 9→  timestamp: string;
10→  severity: Severity;
11→};
12→
13→const cooldowns = new Map<string, number>();
14→const COOLDOWN_MS = 60 * 60 * 1000; // 1 hour
15→const MAX_ALERTS = 50;
16→const recentAlerts: StoredAlert[] = [];
17→let alertCounter = 0;
18→
19→export async function triggerAlert(opts: {
20→  event_type: string;
21→  message: string;
22→  severity: Severity;
23→}): Promise<void> {
24→  const lastFired = cooldowns.get(opts.event_type) ?? 0;
25→  if (Date.now() - lastFired < COOLDOWN_MS) return;
26→  cooldowns.set(opts.event_type, Date.now());
27→
28→  const timestamp = new Date().toISOString();
29→
30→  // Always store in-memory for client polling (even without webhook configured)
31→  const alert: StoredAlert = {
32→    id: `alert-${++alertCounter}`,
33→    event_type: opts.event_type,
34→    message: opts.message,
35→    timestamp,
36→    severity: opts.severity,
37→  };
38→  if (recentAlerts.length >= MAX_ALERTS) recentAlerts.shift();
39→  recentAlerts.push(alert);
40→
41→  // Webhook delivery is optional and fire-and-forget
42→  const webhookUrl = process.env.ALERT_WEBHOOK_URL;
43→  if (!webhookUrl) return;
44→
45→  const controller = new AbortController();
46→  const timeout = setTimeout(() => controller.abort(), 5000);
47→  try {
48→    await fetch(webhookUrl, {
49→      method: 'POST',
50→      headers: { 'Content-Type': 'application/json' },
51→      body: JSON.stringify({
52→        event_type: opts.event_type,
53→        message: opts.message,
54→        timestamp,
55→        severity: opts.severity,
56→      }),
57→      signal: controller.signal,
58→    });
59→  } catch (err) {
60→    logger.warn('webhook alert failed', {
61→      event_type: opts.event_type,
62→      error: String(err),
63→    });
64→  } finally {
65→    clearTimeout(timeout);
66→  }
67→}
68→
69→/** Returns all unacknowledged alerts (oldest first). */
70→export function getRecentAlerts(): StoredAlert[] {
71→  return [...recentAlerts];
72→}
73→
74→/** Remove an alert by id (user acknowledged it). Returns true if found. */
75→export function acknowledgeAlert(alertId: string): boolean {
76→  const idx = recentAlerts.findIndex(a => a.id === alertId);
77→  if (idx === -1) return false;
78→  recentAlerts.splice(idx, 1);
79→  return true;
80→}
81→
82→// For testing: reset all module-level state
83→export function _resetAlerter(): void {
84→  cooldowns.clear();
85→  recentAlerts.length = 0;
86→  alertCounter = 0;
87→}
