    **1. Modify `signIn` function to handle TOTP intermediate state:**

    After `res = await post(serverConfig.SIGNUP_SERVER + '/login', loginInfo);` (line 262), add handling for TOTP:

    ```typescript
    // Check for TOTP challenge (server returns needsTotp when 2FA is enrolled)
    if ((res as any).needsTotp && (res as any).totpNonce) {
      return {
        needsTotp: true,
        totpNonce: (res as any).totpNonce,
      };
    }
    ```

    This must come BEFORE the `if (res.returnUrl)` check and BEFORE the `if (!res.token)` throw.

    Update the signIn return type in the AuthHandlers type to include `needsTotp` and `totpNonce`:
    The function currently returns `{}` on success, `{ error }` on failure, `{ redirectUrl }` for OpenID. Add `{ needsTotp: true, totpNonce: string }` as a possible return.

    **2. Add new IPC handler for TOTP challenge completion:**

    ```typescript
    async function verifyTotp({ totpNonce, code }: { totpNonce: string; code: string }) {
      const serverConfig = getServer();
      if (!serverConfig) {
        throw new Error('No sync server configured.');
      }
      try {
        const res = await post(serverConfig.SIGNUP_SERVER + '/totp/challenge', {
          totpNonce,
          code,
        });
        if (!res.token) {
          return { error: 'invalid-totp-code' };
        }
        await asyncStorage.setItem('user-token', res.token);
        return {};
      } catch (err) {
        if (err instanceof PostError) {
          return { error: err.reason || 'invalid-totp-code' };
        }
        throw err;
      }
    }
    ```

    **3. Add TOTP management IPC handlers:**

    Create these handler functions:

    ```typescript
    async function totpSetup() {
      const serverConfig = getServer();
      if (!serverConfig) throw new Error('No sync server configured.');
      try {
        const res = await post(serverConfig.SIGNUP_SERVER + '/totp/setup', {});
        return res; // { qrCodeUri, secret, recoveryCodes }
      } catch (err) {
        if (err instanceof PostError) return { error: err.reason };
        throw err;
      }
    }

    async function totpVerifySetup({ code }: { code: string }) {
      const serverConfig = getServer();
      if (!serverConfig) throw new Error('No sync server configured.');
      try {
        await post(serverConfig.SIGNUP_SERVER + '/totp/verify-setup', { code });
        return {};
      } catch (err) {
        if (err instanceof PostError) return { error: err.reason };
        throw err;
      }
    }

    async function totpDisable({ password }: { password: string }) {
      const serverConfig = getServer();
      if (!serverConfig) throw new Error('No sync server configured.');
      try {
        await post(serverConfig.SIGNUP_SERVER + '/totp/disable', { password });
        return {};
      } catch (err) {
        if (err instanceof PostError) return { error: err.reason };
        throw err;
      }
    }

    async function totpStatus() {
      const serverConfig = getServer();
      if (!serverConfig) throw new Error('No sync server configured.');
      try {
        return await get(serverConfig.SIGNUP_SERVER + '/totp/status');
      } catch (err) {
        if (err instanceof PostError) return { error: err.reason };
        throw err;
      }
    }

    async function backupStatus() {
      const serverConfig = getServer();
      if (!serverConfig) throw new Error('No sync server configured.');
      try {
        return await get(serverConfig.SIGNUP_SERVER + '/backup/status');
      } catch (err) {
        if (err instanceof PostError) return { error: err.reason };
        throw err;
      }
    }

    async function backupTrigger() {
      const serverConfig = getServer();
      if (!serverConfig) throw new Error('No sync server configured.');
      try {
        return await post(serverConfig.SIGNUP_SERVER + '/backup/trigger', {});
      } catch (err) {
        if (err instanceof PostError) return { error: err.reason };
        throw err;
      }
    }
    ```

