    **2. Modify `onSubmitPassword`:**
    ```typescript
    async function onSubmitPassword() {
      if (password === '' || loading) return;
      setError(null);
      setLoading(true);
      const result = await send('subscribe-sign-in', {
        password,
        loginMethod: 'password',
      });
      setLoading(false);

      if (result.error) {
        setError(result.error);
      } else if (result.needsTotp) {
        setTotpNonce(result.totpNonce);
      } else {
        dispatch(loggedIn());
      }
    }
    ```

    **3. Add `onSubmitTotp` function:**
    ```typescript
    async function onSubmitTotp() {
      if (totpCode === '' || loading) return;
      setError(null);
      setLoading(true);
      const { error } = await send('verify-totp', {
        totpNonce,
        code: totpCode,
      });
      setLoading(false);

      if (error) {
        setError(error);
      } else {
        dispatch(loggedIn());
      }
    }
    ```

