183→    async function verifyTotp({ totpNonce, code }: { totpNonce: string; code: string }) {
184→      const serverConfig = getServer();
185→      if (!serverConfig) {
186→        throw new Error('No sync server configured.');
187→      }
188→      try {
189→        const res = await post(serverConfig.SIGNUP_SERVER + '/totp/challenge', {
