191→          code,
192→        });
193→        if (!res.token) {
194→          return { error: 'invalid-totp-code' };
195→        }
196→        await asyncStorage.setItem('user-token', res.token);
197→        return {};
198→      } catch (err) {
199→        if (err instanceof PostError) {
200→          return { error: err.reason || 'invalid-totp-code' };
201→        }
202→        throw err;
203→      }
204→    }
