  8→function isValidPassword(password: unknown): password is string {
  9→  return password != null && password !== '';
 10→}
 11→
 12→function validatePasswordStrength(password: string): { error?: string } {
 13→  if (password.length < 8) {
 14→    return { error: 'password-too-short' };
 15→  }
 16→  return {};
 17→}
 18→
 19→function hashPassword(password: string): string {
 20→  return bcrypt.hashSync(password, 12);
 21→}
 22→
 23→interface PasswordResult {
 24→  error?: string;
 25→  token?: string;
 26→}
 27→
 28→export function bootstrapPassword(password: string): PasswordResult {
 29→  if (!isValidPassword(password)) {
 30→    return { error: 'invalid-password' };
 31→  }
 32→
 33→  const strengthCheck = validatePasswordStrength(password);
 34→  if (strengthCheck.error) {
 35→    return strengthCheck;
 36→  }
 37→
 38→  const hashed = hashPassword(password);
 39→  const accountDb = getAccountDb();
 40→  accountDb.transaction(() => {
 41→    accountDb.mutate('DELETE FROM auth WHERE method = ?', ['password']);
 42→    accountDb.mutate('UPDATE auth SET active = 0');
 43→    accountDb.mutate(
 44→      "INSERT INTO auth (method, display_name, extra_data, active) VALUES ('password', 'Password', ?, 1)",
 45→      [hashed],
 46→    );
 47→  });
 48→
 49→  return {};
 50→}
 51→
 52→export function loginWithPassword(password: string): PasswordResult {
 53→  if (!isValidPassword(password)) {
 54→    return { error: 'invalid-password' };
 55→  }
 56→
 57→  const accountDb = getAccountDb();
 58→  const authRow = accountDb.first(
 59→    'SELECT extra_data FROM auth WHERE method = ?',
 60→    ['password'],
 61→  );
 62→  const passwordHash = (authRow as { extra_data?: string } | null)?.extra_data;
 63→
 64→  if (!passwordHash) {
 65→    return { error: 'invalid-password' };
 66→  }
 67→
 68→  const confirmed = bcrypt.compareSync(password, passwordHash);
 69→
 70→  if (!confirmed) {
 71→    return { error: 'invalid-password' };
 72→  }
 73→
 74→  const sessionRow = accountDb.first(
 75→    'SELECT * FROM sessions WHERE auth_method = ?',
 76→    ['password'],
 77→  ) as { token?: string } | null;
 78→
 79→  const token = sessionRow ? sessionRow.token! : uuidv4();
 80→
 81→  const countRow = accountDb.first(
 82→    'SELECT count(*) as totalOfUsers FROM users',
 83→  ) as { totalOfUsers: number };
 84→  let userId: string | null = null;
 85→  if (countRow.totalOfUsers === 0) {
 86→    userId = uuidv4();
 87→    accountDb.mutate(
 88→      'INSERT INTO users (id, user_name, display_name, enabled, owner, role) VALUES (?, ?, ?, 1, 1, ?)',
 89→      [userId, '', '', 'ADMIN'],
 90→    );
 91→  } else {
 92→    const userRow = accountDb.first(
 93→      'SELECT id FROM users WHERE user_name = ?',
 94→      [''],
 95→    ) as { id?: string } | null;
 96→
 97→    userId = userRow?.id ?? null;
 98→
 99→    if (!userId) {
100→      return { error: 'user-not-found' };
101→    }
102→  }
103→
104→  let expiration: number = TOKEN_EXPIRATION_NEVER;
105→  const tokenExp = config.get('token_expiration');
106→  if (
107→    tokenExp !== 'never' &&
108→    tokenExp !== 'openid-provider' &&
109→    typeof tokenExp === 'number'
110→  ) {
111→    expiration = Math.floor(Date.now() / 1000) + tokenExp * 60;
112→  }
113→
114→  if (!sessionRow) {
115→    accountDb.mutate(
116→      'INSERT INTO sessions (token, expires_at, user_id, auth_method) VALUES (?, ?, ?, ?)',
117→      [token, expiration, userId, 'password'],
118→    );
119→  } else {
120→    accountDb.mutate(
121→      'UPDATE sessions SET user_id = ?, expires_at = ? WHERE token = ?',
122→      [userId, expiration, token],
123→    );
124→  }
125→
126→  clearExpiredSessions();
127→
128→  return { token };
129→}
