131→export function changePassword(newPassword: string): { error?: string } {
132→  const accountDb = getAccountDb();
133→
134→  if (!isValidPassword(newPassword)) {
135→    return { error: 'invalid-password' };
136→  }
137→
138→  const strengthCheck = validatePasswordStrength(newPassword);
139→  if (strengthCheck.error) {
140→    return strengthCheck;
141→  }
142→
143→  const hashed = hashPassword(newPassword);
144→  accountDb.mutate("UPDATE auth SET extra_data = ? WHERE method = 'password'", [
145→    hashed,
146→  ]);
147→  return {};
148→}
