 77→export function applyJitter(delay: number, jitterFraction: number): number {
 78→  // jitter range: [-fraction, +fraction] of the delay
 79→  const jitter = (Math.random() * 2 - 1) * jitterFraction;
 80→  return Math.round(delay * (1 + jitter));
