 83→export async function syncAccountWithRetry(
 84→  syncFn: () => Promise<void>,
 85→  sleepFn: (ms: number) => Promise<void>,
 86→  policy: RetryPolicy,
 87→  accountLabel: string,
 88→): Promise<void> {
 89→  let delay = policy.initialDelay;
 90→
 91→  for (let attempt = 0; attempt <= policy.maxRetries; attempt++) {
 92→    try {
 93→      await syncFn();
 94→      return; // success
 95→    } catch (err) {
 96→      // RateLimitError and SessionExpiredError bypass retry - propagate immediately
 97→      if (err instanceof RateLimitError || err instanceof SessionExpiredError) {
 98→        throw err;
 99→      }
100→      if (attempt === policy.maxRetries) {
101→        // Final attempt exhausted - propagate to caller for eb_sync_log write
102→        throw err;
103→      }
104→      // Cap base delay before applying jitter so jitter may slightly exceed maxDelay
105→      const cappedDelay = Math.min(delay, policy.maxDelay);
106→      const jitteredDelay = applyJitter(cappedDelay, policy.jitterFraction);
107→      logger.info('Retrying sync', {
108→        attempt: attempt + 1,
109→        maxRetries: policy.maxRetries,
110→        accountLabel,
111→        delayMs: jitteredDelay,
112→      });
113→      await sleepFn(jitteredDelay);
114→      delay = Math.min(delay * policy.multiplier, policy.maxDelay);
115→    }
116→  }
117→}
118→
119→const DEFAULT_RETRY_POLICY: RetryPolicy = {
120→  maxRetries: 3,
121→  initialDelay: 5000,
122→  multiplier: 2,
123→  maxDelay: 60000,
124→  jitterFraction: 0.2,
125→};
126→
127→async function runScheduledSync(): Promise<void> {
128→  logger.info('Starting scheduled sync run');
129→
130→  const db = getAccountDb();
131→
132→  const rows = db.all(
133→    `SELECT m.actual_account_id, m.eb_account_uid, m.session_id,
134→            s.valid_until, s.aspsp_name
135→     FROM eb_account_map m
136→     JOIN eb_sessions s ON s.id = m.session_id
137→     WHERE m.actual_account_id IS NOT NULL
138→     ORDER BY m.session_id`,
139→    [],
140→  ) as unknown as AccountRow[];
141→
142→  // Group accounts by session so consent expiry is checked once per bank
143→  // connection and one session's failure doesn't block other users.
144→  const sessionGroups = new Map<string, AccountRow[]>();
145→  for (const row of rows) {
146→    const group = sessionGroups.get(row.session_id) ?? [];
147→    group.push(row);
148→    sessionGroups.set(row.session_id, group);
149→  }
150→
151→  let totalSessions = 0;
152→  let totalSynced = 0;
153→  let totalErrors = 0;
154→
155→  for (const [sessionId, accounts] of sessionGroups) {
156→    totalSessions++;
157→    const aspspName = accounts[0]?.aspsp_name ?? 'unknown';
158→    const validUntil = accounts[0]?.valid_until;
159→
160→    // Check consent expiry once per session group.
161→    if (validUntil) {
162→      const expiryDate = new Date(validUntil);
163→      const now = new Date();
164→      const daysUntilExpiry =
165→        (expiryDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24);
166→
167→      if (expiryDate < now) {
168→        // Already expired - skip this session
169→        logger.warn('Skipping expired session', {
170→          sessionId,
171→          aspspName,
172→          accounts: accounts.length,
173→        });
174→        triggerAlert({
175→          event_type: 'consent_expiry',
176→          message: `Consent expired for ${aspspName} (session ${sessionId}, ${accounts.length} accounts)`,
177→          severity: 'error',
178→        }).catch(() => {});
179→        continue;
180→      } else if (daysUntilExpiry <= 14) {
181→        // Expiring within 14 days - alert but continue syncing
182→        logger.warn('Consent expiring soon', {
183→          sessionId,
184→          aspspName,
185→          daysUntilExpiry: Math.round(daysUntilExpiry),
186→        });
187→        triggerAlert({
188→          event_type: 'consent_expiry',
189→          message: `Consent for ${aspspName} expires in ${Math.round(daysUntilExpiry)} days (session ${sessionId})`,
190→          severity: 'warning',
191→        }).catch(() => {});
192→      }
193→    }
194→
195→    let successCount = 0;
196→
197→    for (const account of accounts) {
198→      try {
199→        await syncAccountWithRetry(
200→          () => syncOneAccount(account),
201→          sleep,
202→          DEFAULT_RETRY_POLICY,
203→          account.actual_account_id,
204→        );
205→        successCount++;
206→        totalSynced++;
207→      } catch (err) {
208→        if (err instanceof RateLimitError) {
209→          // A 429 applies to the entire API connection - don't sleep or retry.
210→          logger.warn('Rate limited, skipping session', { sessionId, aspspName });
211→          break;
212→        }
213→        if (err instanceof SessionExpiredError) {
214→          logger.warn('Session expired mid-sync', { sessionId });
215→          break;
216→        }
217→        // All retries exhausted - log error to eb_sync_log
218→        logger.error('Sync failed after retries exhausted', {
219→          accountId: account.actual_account_id,
220→          maxRetries: DEFAULT_RETRY_POLICY.maxRetries,
221→          error: err instanceof Error ? err.message : String(err),
222→        });
223→        triggerAlert({
224→          event_type: 'sync_failure',
225→          message: `Sync failed for account ${account.actual_account_id} after ${DEFAULT_RETRY_POLICY.maxRetries} retries: ${err instanceof Error ? err.message : String(err)}`,
226→          severity: 'error',
227→        }).catch(() => {});
228→        const retryDb = getAccountDb();
229→        retryDb.mutate(
230→          `INSERT INTO eb_sync_log (actual_account_id, eb_account_uid, status, error_message)
231→           VALUES (?, ?, 'error', ?)`,
232→          [
233→            account.actual_account_id,
234→            account.eb_account_uid,
235→            err instanceof Error ? err.message : String(err),
236→          ],
237→        );
238→        totalErrors++;
239→      }
240→    }
241→
242→    logger.info('Session sync complete', {
243→      sessionId,
244→      aspspName,
245→      synced: successCount,
246→      total: accounts.length,
247→    });
248→  }
249→
250→  logger.info('Sync run complete', {
251→    sessions: totalSessions,
252→    synced: totalSynced,
253→    errors: totalErrors,
254→  });
255→  recordSyncRun(totalSynced, totalErrors);
256→}
257→
258→// [eb] Registers the 6-hour cron job. No-op when ENABLE_AUTO_SYNC is not 'true'.
259→export function startScheduler(): void {
260→  if (process.env.ENABLE_AUTO_SYNC !== 'true') {
261→    logger.info('Auto-sync disabled (ENABLE_AUTO_SYNC not set to true)');
262→    return;
263→  }
264→
265→  // 5-field cron: at minute 0, hours 0/6/12/18 every day
266→  cron.schedule('0 0,6,12,18 * * *', () => {
267→    runScheduledSync().catch(err => {
268→      logger.error('Unhandled error in sync run', {
269→        error: err instanceof Error ? err.message : String(err),
270→      });
271→    });
272→  });
273→
274→  logger.info('Auto-sync scheduled (every 6 hours)');
275→}
