 23→// In-memory auth failure rate tracking per IP for alert triggering.
 24→// Map<ip, { count, windowStart }> -- resets on server restart.
 25→const authFailureTracker = new Map<string, { count: number; windowStart: number }>();
 26→const AUTH_FAILURE_WINDOW_MS = 5 * 60 * 1000; // 5 minutes
 27→const AUTH_FAILURE_THRESHOLD = 3;
 28→
 29→function trackAuthFailure(ip: string): void {
 30→  const now = Date.now();
 31→  const entry = authFailureTracker.get(ip);
 32→  if (!entry || now - entry.windowStart > AUTH_FAILURE_WINDOW_MS) {
 33→    authFailureTracker.set(ip, { count: 1, windowStart: now });
 34→    return;
 35→  }
 36→  entry.count++;
 37→  if (entry.count >= AUTH_FAILURE_THRESHOLD) {
 38→    triggerAlert({
 39→      event_type: 'auth_failure_burst',
 40→      message: `${entry.count} authentication failures from IP ${ip} in ${Math.round((now - entry.windowStart) / 1000)}s`,
 41→      severity: 'warning',
 42→    }).catch(() => {}); // fire-and-forget
 43→    // Reset counter after alerting to avoid spamming (cooldown handles rapid re-fires)
 44→    authFailureTracker.delete(ip);
 45→  }
 46→}
