 98→app.post('/login', async (req: Request, res: Response) => {
 99→  const loginMethod = getLoginMethod(req);
100→  logger.info('Login attempt', { method: loginMethod });
101→  let tokenRes: { error?: string; token?: string } | null = null;
102→  switch (loginMethod) {
103→    case 'header': {
104→      const headerVal = req.get('x-actual-password') || '';
105→      const obfuscated =
106→        '*'.repeat(headerVal.length) || 'No password provided.';
107→      console.debug('HEADER VALUE: ' + obfuscated);
108→      if (headerVal === '') {
109→        res.send({ status: 'error', reason: 'invalid-header' });
110→        writeAuditLog({ event_type: 'login_failure', actor: 'unauthenticated', ip_address: req.ip, outcome: 'fail', details: { reason: 'invalid-header', method: 'header' } });
111→        trackAuthFailure(req.ip ?? 'unknown');
112→        return;
113→      } else {
114→        if (validateAuthHeader(req)) {
115→          tokenRes = loginWithPassword(headerVal);
116→        } else {
117→          res.send({ status: 'error', reason: 'proxy-not-trusted' });
118→          writeAuditLog({ event_type: 'login_failure', actor: 'unauthenticated', ip_address: req.ip, outcome: 'fail', details: { reason: 'proxy-not-trusted', method: 'header' } });
119→          trackAuthFailure(req.ip ?? 'unknown');
120→          return;
121→        }
122→      }
123→      break;
124→    }
125→    case 'openid': {
126→      if (!isValidRedirectUrl(req.body.returnUrl)) {
127→        res
128→          .status(400)
129→          .send({ status: 'error', reason: 'Invalid redirect URL' });
130→        return;
131→      }
132→
133→      const { error, url } = await loginWithOpenIdSetup(
134→        req.body.returnUrl,
135→        req.body.password,
136→      );
137→      if (error) {
138→        res.status(400).send({ status: 'error', reason: error });
139→        return;
140→      }
141→      res.send({ status: 'ok', data: { returnUrl: url } });
142→      return;
143→    }
144→
145→    default:
146→      tokenRes = loginWithPassword(req.body.password);
147→      break;
148→  }
149→  const { error, token } = tokenRes!;
150→
151→  if (error) {
152→    writeAuditLog({
153→      event_type: 'login_failure',
154→      actor: 'unauthenticated',
155→      ip_address: req.ip,
156→      outcome: 'fail',
157→      details: { reason: error, method: loginMethod },
158→    });
159→    trackAuthFailure(req.ip ?? 'unknown');
160→    res.status(400).send({ status: 'error', reason: error });
161→    return;
162→  }
163→
164→  writeAuditLog({
165→    event_type: 'login_success',
166→    actor: token!,
167→    ip_address: req.ip,
168→    outcome: 'success',
169→    details: { method: loginMethod },
170→  });
171→  res.send({ status: 'ok', data: { token } });
172→});
