 13→export function getAccountDb(): WrappedDatabase {
 14→  if (_accountDb === undefined) {
 15→    const dbPath = join(resolve(config.get('serverFiles')), 'account.sqlite');
 16→    _accountDb = openDatabase(dbPath);
 17→  }
 18→
 19→  return _accountDb;
