 22→// Closes and resets the singleton database handle. Used in test teardown so
 23→// the SQLite file is not locked when migrations attempt to delete it (EBUSY
 24→// on Windows occurs when better-sqlite3 holds an open file handle during rm).
 25→export function closeAccountDb(): void {
 26→  if (_accountDb !== undefined) {
 27→    _accountDb.close();
 28→    _accountDb = undefined;
 29→  }
 30→}
 31→
 32→export function needsBootstrap(): boolean {
 33→  const accountDb = getAccountDb();
 34→  const rows = accountDb.all('SELECT * FROM auth');
 35→  return rows.length === 0;
 36→}
