 38→interface LoginMethodRow {
 39→  method: string;
 40→  active: number;
 41→  display_name: string;
 42→}
 43→
 44→interface LoginMethodResult {
 45→  method: string;
 46→  active: number;
 47→  displayName: string;
 48→}
 49→
 50→export function listLoginMethods(): LoginMethodResult[] {
 51→  const accountDb = getAccountDb();
 52→  const rows = accountDb.all(
 53→    'SELECT method, display_name, active FROM auth',
 54→  ) as unknown as LoginMethodRow[];
 55→  return rows
 56→    .filter(f =>
 57→      rows.length > 1 && config.get('enforceOpenId')
 58→        ? f.method === 'openid'
 59→        : true,
 60→    )
 61→    .map(r => ({
 62→      method: r.method,
 63→      active: r.active,
 64→      displayName: r.display_name,
 65→    }));
 66→}
