 68→export function getActiveLoginMethod(): string | undefined {
 69→  const accountDb = getAccountDb();
 70→  const row = accountDb.first('SELECT method FROM auth WHERE active = 1');
 71→  return (row as { method?: string } | null)?.method;
 72→}
