 74→/*
 75→ * Get the Login Method in the following order
 76→ * req (the frontend can say which method in the case it wants to resort to forcing password auth)
 77→ * config options
 78→ * fall back to using password
 79→ */
 80→export function getLoginMethod(req?: {
 81→  body?: { loginMethod?: string };
 82→}): string {
 83→  if (
 84→    typeof req !== 'undefined' &&
 85→    (req.body || { loginMethod: null }).loginMethod &&
 86→    config.get('allowedLoginMethods').includes(req.body!.loginMethod!)
 87→  ) {
 88→    return req.body!.loginMethod!;
 89→  }
 90→
 91→  //BY-PASS ANY OTHER CONFIGURATION TO ENSURE HEADER AUTH
 92→  if (
 93→    config.get('loginMethod') === 'header' &&
 94→    config.get('allowedLoginMethods').includes('header')
 95→  ) {
 96→    return config.get('loginMethod');
 97→  }
 98→
 99→  const activeMethod = getActiveLoginMethod();
100→  return activeMethod || config.get('loginMethod');
101→}
