103→interface LoginSettings {
104→  password?: string;
105→  openId?: Record<string, unknown>;
106→}
107→
108→interface BootstrapResult {
109→  error?: string;
110→  token?: string;
111→}
112→
113→export async function bootstrap(
114→  loginSettings: LoginSettings | null,
115→  forced: boolean = false,
116→): Promise<BootstrapResult> {
117→  if (!loginSettings) {
118→    return { error: 'invalid-login-settings' };
119→  }
120→  const passEnabled = 'password' in loginSettings;
121→  const openIdEnabled = 'openId' in loginSettings;
122→
123→  const accountDb = getAccountDb();
124→  accountDb.mutate('BEGIN TRANSACTION');
125→  try {
126→    const countRow = accountDb.first(
127→      `SELECT count(*) as countOfOwner
128→   FROM users
129→   WHERE users.user_name <> '' and users.owner = 1`,
130→    );
131→    const countOfOwner =
132→      (countRow as { countOfOwner?: number } | null)?.countOfOwner ?? 0;
133→
134→    if (!forced && (!openIdEnabled || countOfOwner > 0)) {
135→      if (!needsBootstrap()) {
136→        accountDb.mutate('ROLLBACK');
137→        return { error: 'already-bootstrapped' };
138→      }
139→    }
140→
141→    if (!passEnabled && !openIdEnabled) {
142→      accountDb.mutate('ROLLBACK');
143→      return { error: 'no-auth-method-selected' };
144→    }
145→
146→    if (passEnabled && openIdEnabled && !forced) {
147→      accountDb.mutate('ROLLBACK');
148→      return { error: 'max-one-method-allowed' };
149→    }
150→
151→    if (passEnabled) {
152→      const { error } = bootstrapPassword(loginSettings.password!);
153→      if (error) {
154→        accountDb.mutate('ROLLBACK');
155→        return { error };
156→      }
157→    }
