44→export function validateAuthHeader(req: Request) {
45→  // fallback to trustedProxies when trustedAuthProxies not set
46→  const trustedAuthProxies: string[] =
47→    config.get('trustedAuthProxies') ?? config.get('trustedProxies');
48→  // ensure the first hop from our server is trusted
49→  const peer = req.socket.remoteAddress;
50→  if (peer === undefined) {
51→    console.error(`Header Auth Login attempted but there was no defined peer.`);
