55→  const rangeList = {
56→    allowed_ips: trustedAuthProxies.map(q => ipaddr.parseCIDR(q)),
57→  };
58→
59→  const matched = ipaddr.subnetMatch(peerIp, rangeList, 'fail');
60→
61→  if (matched === 'allowed_ips') {
62→    console.info(`Header Auth Login permitted from ${peer}`);
63→    return true;
64→  } else {
