 43→async function needsBootstrap({ url }: { url?: string } = {}) {
 44→  if (url && !isValidBaseURL(url)) {
 45→    return { error: 'get-server-failure' };
 46→  }
 47→
 48→  let serverConfig: ReturnType<typeof getServer>;
 49→
 50→  try {
 51→    serverConfig = getServer(url);
 52→    if (!serverConfig) {
 53→      return { bootstrapped: true, hasServer: false };
 54→    }
 55→  } catch {
 56→    return { error: 'get-server-failure' };
 57→  }
 58→
 59→  let resText: string;
 60→  try {
 61→    resText = await get(serverConfig.SIGNUP_SERVER + '/needs-bootstrap');
 62→  } catch {
 63→    return { error: 'network-failure' };
 64→  }
 65→
 66→  let res: {
 67→    status: 'ok';
 68→    data: {
 69→      bootstrapped: boolean;
 70→      loginMethod: 'password' | 'openid' | string;
 71→      availableLoginMethods: Array<{
 72→        method: string;
 73→        displayName: string;
 74→        active: boolean;
 75→      }>;
 76→      multiuser: boolean;
 77→    };
 78→  };
 79→
 80→  try {
 81→    res = JSON.parse(resText);
 82→  } catch {
 83→    return { error: 'parse-failure' };
 84→  }
 85→
 86→  return {
 87→    bootstrapped: res.data.bootstrapped,
 88→    availableLoginMethods: res.data.availableLoginMethods || [
 89→      { method: 'password', active: true, displayName: 'Password' },
 90→    ],
 91→    multiuser: res.data.multiuser || false,
 92→    hasServer: true,
 93→  };
 94→}
