  6→import { PostError } from './errors';
  7→
  8→function throwIfNot200(res: Response, text: string) {
  9→  if (res.status !== 200) {
 10→    if (res.status === 500) {
 11→      throw new PostError(res.status === 500 ? 'internal' : text);
 12→    }
 13→
 14→    const contentType = res.headers.get('Content-Type');
 15→    if (contentType.toLowerCase().indexOf('application/json') !== -1) {
 16→      const json = JSON.parse(text);
 17→      throw new PostError(json.reason);
 18→    }
 19→
 20→    // Actual Sync Server may be exposed via a tunnel (e.g. ngrok). Tunnel errors should be treated as network errors.
 21→    const tunnelErrorHeaders = ['ngrok-error-code'];
 22→    const tunnelError = tunnelErrorHeaders.some(header =>
 23→      res.headers.has(header),
 24→    );
 25→
 26→    if (tunnelError) {
 27→      // Tunnel errors are present when the tunnel is active and the server is not reachable e.g. server is offline
 28→      // When we experience a tunnel error we treat it as a network failure
 29→      throw new PostError('network-failure');
 30→    }
 31→
 32→    throw new PostError(text);
 33→  }
 34→}
 35→
 36→export async function post(
 37→  url: RequestInfo,
 38→  data: unknown,
 39→  headers = {},
 40→  timeout: number | null = null,
 41→) {
 42→  let text: string;
 43→  let res: Response;
 44→
 45→  try {
 46→    const controller = new AbortController();
 47→    const timeoutId = setTimeout(() => controller.abort(), timeout);
 48→    const signal = timeout ? controller.signal : null;
 49→    res = await fetch(url, {
 50→      method: 'POST',
 51→      body: JSON.stringify(data),
 52→      signal,
 53→      headers: {
 54→        ...headers,
 55→        'Content-Type': 'application/json',
 56→      },
 57→    });
 58→    clearTimeout(timeoutId);
 59→    text = await res.text();
 60→  } catch {
 61→    throw new PostError('network-failure');
 62→  }
 63→
 64→  throwIfNot200(res, text);
 65→
 66→  let responseData;
 67→
 68→  try {
 69→    responseData = JSON.parse(text);
 70→  } catch (err) {
 71→    logger.log('Failed to parse JSON response: ' + url + '\n' + String(err));
 72→    throw new PostError('parse-json', { meta: text });
 73→  }
 74→
 75→  if (responseData.status !== 'ok') {
 76→    logger.log(
 77→      'API call failed: ' +
 78→        url +
 79→        '\nData: ' +
 80→        JSON.stringify(data, null, 2) +
 81→        '\nResponse: ' +
 82→        JSON.stringify(res, null, 2),
 83→    );
 84→
 85→    throw new PostError(
 86→      responseData.description || responseData.reason || 'unknown',
 87→    );
 88→  }
 89→
 90→  return responseData.data;
 91→}
