 94→  let text;
 95→  let res;
 96→
 97→  try {
 98→    const controller = new AbortController();
 99→    const timeoutId = setTimeout(() => controller.abort(), timeout);
100→    const signal = timeout ? controller.signal : null;
101→    res = await fetch(url, {
102→      method: 'DELETE',
103→      body: JSON.stringify(data),
104→      signal,
105→      headers: {
106→        ...headers,
107→        'Content-Type': 'application/json',
108→      },
109→    });
110→    clearTimeout(timeoutId);
111→    text = await res.text();
112→  } catch {
113→    throw new PostError('network-failure');
114→  }
115→
116→  throwIfNot200(res, text);
117→
118→  try {
119→    res = JSON.parse(text);
120→  } catch (err) {
121→    logger.log('Failed to parse JSON response: ' + url + '\n' + String(err));
122→    throw new PostError('parse-json', { meta: text });
123→  }
124→
125→  if (res.status !== 'ok') {
126→    logger.log(
127→      'API call failed: ' +
128→        url +
129→        '\nData: ' +
130→        JSON.stringify(data, null, 2) +
131→        '\nResponse: ' +
132→        JSON.stringify(res, null, 2),
