141→export async function patch(url, data, headers = {}, timeout = null) {
142→  let text;
143→  let res;
144→
145→  try {
146→    const controller = new AbortController();
147→    const timeoutId = setTimeout(() => controller.abort(), timeout);
148→    const signal = timeout ? controller.signal : null;
149→    res = await fetch(url, {
150→      method: 'PATCH',
151→      body: JSON.stringify(data),
152→      signal,
153→      headers: {
154→        ...headers,
155→        'Content-Type': 'application/json',
156→      },
157→    });
158→    clearTimeout(timeoutId);
159→    text = await res.text();
160→  } catch {
161→    throw new PostError('network-failure');
162→  }
163→
164→  throwIfNot200(res, text);
165→
166→  try {
167→    res = JSON.parse(text);
168→  } catch (err) {
169→    logger.log('Failed to parse JSON response: ' + url + '\n' + String(err));
170→    throw new PostError('parse-json', { meta: text });
171→  }
172→
173→  if (res.status !== 'ok') {
174→    logger.log(
175→      'API call failed: ' +
176→        url +
177→        '\nData: ' +
178→        JSON.stringify(data, null, 2) +
179→        '\nResponse: ' +
180→        JSON.stringify(res, null, 2),
181→    );
182→
183→    throw new PostError(res.description || res.reason || 'unknown');
184→  }
185→
186→  return res.data;
