189→export async function postBinary(url, data, headers) {
190→  let res;
191→  try {
192→    res = await fetch(url, {
193→      method: 'POST',
194→      body: Platform.isBrowser ? data : Buffer.from(data),
195→      headers: {
196→        'Content-Length': data.length,
197→        'Content-Type': 'application/actual-sync',
198→        ...headers,
199→      },
200→    });
201→  } catch {
202→    throw new PostError('network-failure');
203→  }
204→
205→  let buffer;
206→  if (res.arrayBuffer) {
207→    buffer = Buffer.from(await res.arrayBuffer());
208→  } else {
209→    buffer = await res.buffer();
210→  }
211→
212→  throwIfNot200(res, buffer.toString());
213→
214→  return buffer;
215→}
216→
217→export function get(url, opts?) {
218→  return fetch(url, opts).then(res => res.text());
219→}
