303→export function Login() {
304→  const { t } = useTranslation();
305→  const { isNarrowWidth } = useResponsive();
306→
307→  const dispatch = useDispatch();
308→  const defaultLoginMethod = useLoginMethod();
309→  const [method, setMethod] = useState(defaultLoginMethod);
310→  const [searchParams, _setSearchParams] = useSearchParams();
311→  const [error, setError] = useState(null);
312→  const { checked } = useBootstrapped();
313→  const loginMethods = useAvailableLoginMethods();
314→  const loginMethodRef = useRef<HTMLButtonElement>(null);
315→  const [loginMethodMenuOpen, setLoginMethodMenuOpen] = useState(false);
316→
317→  useEffect(() => {
318→    setMethod(defaultLoginMethod);
319→  }, [defaultLoginMethod]);
320→
321→  useEffect(() => {
322→    if (checked && !searchParams.has('error')) {
323→      (async () => {
324→        if (method === 'header') {
325→          setError(null);
326→          const { error } = await send('subscribe-sign-in', {
327→            password: '',
328→            loginMethod: method,
329→          });
330→
331→          if (error) {
332→            setError(error);
333→          } else {
334→            dispatch(loggedIn());
335→          }
336→        }
337→      })();
338→    }
339→  }, [loginMethods, checked, searchParams, method, dispatch]);
340→
341→  function getErrorMessage(error) {
342→    switch (error) {
343→      case 'invalid-header':
344→        return t('Auto login failed - No header sent');
345→      case 'proxy-not-trusted':
346→        return t('Auto login failed - Proxy not trusted');
347→      case 'invalid-password':
348→        return t('Invalid password');
349→      case 'network-failure':
350→        return t('Unable to contact the server');
351→      case 'internal-error':
352→        return t('Internal error');
353→      default:
354→        return t(`An unknown error occurred: {{error}}`, { error });
355→    }
356→  }
357→
358→  if (!checked) {
359→    return null;
360→  }
361→
362→  return (
363→    <View style={{ maxWidth: 450, marginTop: -30, color: theme.pageText }}>
364→      <Title text={t('Sign in to this Actual instance')} />
365→
366→      {loginMethods?.length > 1 && (
367→        <Text
368→          style={{
369→            fontSize: 16,
370→            color: theme.pageTextDark,
371→            lineHeight: 1.4,
372→            marginBottom: 10,
373→          }}
374→        >
375→          <Trans>
376→            If you lost your password, you likely still have access to your
377→            server to manually reset it.
378→          </Trans>
379→        </Text>
380→      )}
381→
382→      {method === 'password' && (
383→        <PasswordLogin setError={setError} dispatch={dispatch} />
384→      )}
385→
386→      {method === 'openid' && <OpenIdLogin setError={setError} />}
387→
388→      {method === 'header' && <HeaderLogin error={error} />}
389→
390→      {loginMethods?.length > 1 && (
391→        <View style={{ marginTop: 10 }}>
392→          <View
393→            style={{
394→              width: '100%',
395→              flexDirection: 'row',
396→              justifyContent: 'end',
397→            }}
398→          >
399→            <Button
400→              variant="bare"
401→              ref={loginMethodRef}
402→              onPress={() => setLoginMethodMenuOpen(true)}
403→              style={{
404→                ...styles.verySmallText,
405→                color: theme.pageTextLight,
406→                paddingTop: 5,
407→                width: 'fit-content',
408→                ...(isNarrowWidth ? { padding: 10 } : null),
409→              }}
410→            >
411→              <Trans>Select the login method</Trans>{' '}
412→              <SvgCheveronDown width={12} height={12} />
413→            </Button>
414→          </View>
415→          <Popover
416→            triggerRef={loginMethodRef}
417→            onOpenChange={value => {
418→              setLoginMethodMenuOpen(value);
419→            }}
420→            isOpen={loginMethodMenuOpen}
421→          >
422→            <Menu
423→              items={loginMethods
424→                ?.filter(f => f.method !== method)
425→                .map(m => ({
426→                  name: m.method,
427→                  text: m.displayName,
428→                }))}
429→              onMenuSelect={selected => {
430→                setError(null);
431→                setMethod(selected);
432→                setLoginMethodMenuOpen(false);
433→              }}
434→            />
435→          </Popover>
436→        </View>
437→      )}
438→
439→      {error && (
440→        <Text
441→          role="alert"
442→          style={{
443→            marginTop: 20,
444→            color: theme.errorText,
445→            borderRadius: 4,
446→            fontSize: 15,
447→          }}
448→        >
449→          {getErrorMessage(error)}
450→        </Text>
451→      )}
452→    </View>
453→  );
454→}
