function PasswordLogin({ setError, dispatch }) {
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [totpNonce, setTotpNonce] = useState<string | null>(null);
  const [totpCode, setTotpCode] = useState('');
  const { t } = useTranslation();
  const { isNarrowWidth } = useResponsive();

  async function onSubmitPassword() {
    if (password === '' || loading) {
      return;
    }

    setError(null);
    setLoading(true);
    const result = await send('subscribe-sign-in', {
      password,
      loginMethod: 'password',
    });
    setLoading(false);

    if (result.error) {
      setError(result.error);
    } else if (result.needsTotp) {
      setTotpNonce(result.totpNonce);
    } else {
      dispatch(loggedIn());
    }
  }

  async function onSubmitTotp() {
    if (totpCode === '' || loading) {
      return;
    }
    setError(null);
    setLoading(true);
    const { error } = await send('verify-totp', {
      totpNonce,
      code: totpCode,
    });
    setLoading(false);

    if (error) {
      setError(error);
    } else {
      dispatch(loggedIn());
    }
  }

  if (totpNonce) {
    return (
      <View style={{ flexDirection: 'column', marginTop: 5, gap: '1rem' }}>
        <Text style={{ fontSize: 15, color: theme.pageText }}>
          {t(
            'Enter the 6-digit code from your authenticator app, or a recovery code.',
          )}
        </Text>
        <BigInput
          autoFocus
          aria-label={t('Authentication code')}
          placeholder={t('6-digit code or recovery code')}
          type="text"
          inputMode="numeric"
          autoComplete="one-time-code"
          onChangeValue={setTotpCode}
          style={{ flex: 1 }}
          onEnter={onSubmitTotp}
          required
        />
        <View
          style={{
            flexDirection: isNarrowWidth ? 'column' : 'row',
            gap: '0.5rem',
          }}
        >
          <ButtonWithLoading
            variant="primary"
            isLoading={loading}
            style={{
              fontSize: 15,
              width: isNarrowWidth ? '100%' : 170,
            }}
            onPress={onSubmitTotp}
          >
            <Trans>Verify</Trans>
          </ButtonWithLoading>
          <Button
            variant="bare"
            onPress={() => {
              setTotpNonce(null);
              setTotpCode('');
              setError(null);
            }}
          >
            <Trans>Back</Trans>
          </Button>
        </View>
      </View>
    );
  }

  return (
    <View
      style={{
        flexDirection: isNarrowWidth ? 'column' : 'row',
        marginTop: 5,
        gap: '1rem',
      }}
    >
      <BigInput
        autoFocus
        aria-label={t('Password')}
        placeholder={t('Password')}
        type="password"
        onChangeValue={setPassword}
        style={{ flex: 1 }}
        onEnter={onSubmitPassword}
        required
      />
      <ButtonWithLoading
        variant="primary"
        isLoading={loading}
        style={{
          fontSize: 15,
          width: isNarrowWidth ? '100%' : 170,
          ...(isNarrowWidth ? { padding: 10 } : null),
        }}
        onPress={onSubmitPassword}
      >
        <Trans>Sign in</Trans>
      </ButtonWithLoading>
    </View>
  );
}

